# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İMAN ESASLARININ TEMEL KAYNAKLARI VE ALTI İMAN İLKESİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">1. KUR\'AN-I KERİM (BİRİNCİL KAYNAK)</text>\n  <text x="35" y="92" font-size="10.5" font-weight="bold" fill="#14532d">• İhlâs Suresi (1-4. Ayetler):</text>\n  <text x="45" y="108" font-size="10" fill="#166534">Allah\'ın birliği (Ehad), Samed oluşu ve</text>\n  <text x="45" y="122" font-size="10" fill="#166534">hiçbir denginin bulunmadığı (Tevhid özeti).</text>\n  <text x="35" y="144" font-size="10.5" font-weight="bold" fill="#14532d">• Bakara Suresi 177 ve 285 (Âmenerrasûlü):</text>\n  <text x="45" y="160" font-size="10" fill="#166534">Allah\'a, ahirete, meleklere, vahiylere ve</text>\n  <text x="45" y="174" font-size="10" fill="#166534">nebîlere ayrım yapmaksızın iman etme ilkesi.</text>\n  <text x="35" y="196" font-size="10.5" font-weight="bold" fill="#14532d">• Nisâ 136 ve Kamer 49. Ayetler:</text>\n  <text x="45" y="212" font-size="10" fill="#166534">İman esaslarının bütünlüğü ve her şeyin</text>\n  <text x="45" y="226" font-size="10" fill="#166534">ilahi bir ölçüye (kader) göre yaratılması.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">2. SAHİH SÜNNET VE HADİS KAYNAKLARI</text>\n  <text x="375" y="92" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Cibrîl Hadisi (Âmentü Esasları):</text>\n  <text x="385" y="108" font-size="10" fill="#1e40af">1) Allah\'a iman  2) Meleklerine iman</text>\n  <text x="385" y="124" font-size="10" fill="#1e40af">3) İlahi vahiylere iman  4) Peygamberlere iman</text>\n  <text x="385" y="140" font-size="10" fill="#1e40af">5) Ahiret gününe iman  6) Kadere (hayır-şer) iman</text>\n  <text x="375" y="164" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Kütüb-i Sitte (Altı Güvenilir Hadis Eseri):</text>\n  <text x="385" y="180" font-size="10" fill="#1e40af">- Sahîhayn: Buhârî ve Müslim (el-Câmiu\'s-Sahîh)</text>\n  <text x="385" y="196" font-size="10" fill="#1e40af">- Sünen-i Erbaa: Ebû Dâvûd, Tirmizî, Nesâî, İbn Mâce</text>\n  <text x="375" y="220" font-size="10" font-weight="bold" fill="#b91c1c">• İman esasları bölünmez bir bütündür (tecezzi kabul etmez).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">CİBRÎL HADİSİNDE TANIMLANAN ÜÇ TEMEL KAVRAM: İMAN - İSLAM - İHSAN</text>\n  <rect x="20" y="48" width="212" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="126" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">1. İMAN (İNANÇ)</text>\n  <text x="32" y="96" font-size="10.5" font-weight="bold" fill="#1e40af">Kalp ile Tasdik Boyutu:</text>\n  <text x="32" y="116" font-size="10" fill="#1e3a8a">• Allah\'ın varlığına ve birliğine</text>\n  <text x="32" y="134" font-size="10" fill="#1e3a8a">• Meleklerine ve vahiylerine</text>\n  <text x="32" y="152" font-size="10" fill="#1e3a8a">• Bütün peygamberlerine</text>\n  <text x="32" y="170" font-size="10" fill="#1e3a8a">• Ahiret gününe (hesap ve mizana)</text>\n  <text x="32" y="188" font-size="10" fill="#1e3a8a">• Kaderin hayır ve şerrinin</text>\n  <text x="40" y="203" font-size="10" fill="#1e3a8a">Allah\'tan olduğuna inanmak.</text>\n  <rect x="244" y="48" width="212" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">2. İSLAM (AMEL)</text>\n  <text x="256" y="96" font-size="10.5" font-weight="bold" fill="#15803d">İbadet ve Uygulama Boyutu:</text>\n  <text x="256" y="116" font-size="10" fill="#166534">• Kelime-i şehadet getirmek</text>\n  <text x="256" y="134" font-size="10" fill="#166534">• Günde beş vakit namaz kılmak</text>\n  <text x="256" y="152" font-size="10" fill="#166534">• Zekât ibadetini yerine getirmek</text>\n  <text x="256" y="170" font-size="10" fill="#166534">• Ramazan ayında oruç tutmak</text>\n  <text x="256" y="188" font-size="10" fill="#166534">• Yoluna gücü yetenler için</text>\n  <text x="264" y="203" font-size="10" fill="#166534">Kâbe\'yi ziyaret edip haccetmek.</text>\n  <rect x="468" y="48" width="212" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="574" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#78350f">3. İHSAN (AHLAK)</text>\n  <text x="480" y="96" font-size="10.5" font-weight="bold" fill="#b45309">Samimiyet ve Bilinç Boyutu:</text>\n  <text x="480" y="118" font-size="10" fill="#92400e">"Allah\'ı görüyormuşsun gibi</text>\n  <text x="480" y="134" font-size="10" fill="#92400e">O\'na kulluk etmendir; çünkü</text>\n  <text x="480" y="150" font-size="10" fill="#92400e">sen O\'nu görmesen de O seni</text>\n  <text x="480" y="166" font-size="10" fill="#92400e">her an görmektedir."</text>\n  <text x="480" y="192" font-size="10" font-weight="bold" fill="#78350f">→ İman ve ibadetin güzel</text>\n  <text x="488" y="207" font-size="10" font-weight="bold" fill="#78350f">ahlaka dönüşmüş zirvesidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TEVHİD İNANCININ BİREYSEL VE TOPLUMSAL HAYATA KAZANDIRDIKLARI</text>\n  <rect x="20" y="45" width="320" height="90" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">1. KULLUKTA ÖZGÜRLEŞME VE ONUR</text>\n  <text x="35" y="88" font-size="10.5" fill="#78350f">• Yalnızca Allah\'a kulluk eden insan; kula kulluktan,</text>\n  <text x="43" y="104" font-size="10.5" fill="#78350f">mal, makam ve nefis tutsaklığından kurtularak</text>\n  <text x="43" y="120" font-size="10.5" fill="#78350f">yaratılmışların en şereflisi olma onurunu korur.</text>\n  <rect x="360" y="45" width="320" height="90" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. İÇ HUZUR, ÜMİT VE TEVEKKÜL</text>\n  <text x="375" y="88" font-size="10.5" fill="#14532d">• Her şeye gücü yeten ve merhamet eden Allah\'a</text>\n  <text x="383" y="104" font-size="10.5" fill="#14532d">güvenen mümin; yalnızlık ve çaresizlik korkusuna</text>\n  <text x="383" y="120" font-size="10.5" fill="#14532d">kapılmaz, elinden geleni yapıp tevekkül eder.</text>\n  <rect x="20" y="150" width="320" height="90" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="171" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">3. HURAFE VE ŞİRKTEN KURTULUŞ</text>\n  <text x="35" y="193" font-size="10.5" fill="#1e3a8a">• Tevhid bilinci; falcılık, büyü, uğursuzluk ve</text>\n  <text x="43" y="209" font-size="10.5" fill="#1e3a8a">tabiat güçlerine tapınma gibi batıl inançları yıkar,</text>\n  <text x="43" y="225" font-size="10.5" fill="#1e3a8a">insanı akıl, ilim ve sünnetullahı anlamaya yöneltir.</text>\n  <rect x="360" y="150" width="320" height="90" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="171" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">4. ADALET VE AHLAKİ SORUMLULUK</text>\n  <text x="375" y="193" font-size="10.5" fill="#581c87">• Allah\'ın her an kendisini gördüğünü ve ahirette</text>\n  <text x="383" y="209" font-size="10.5" fill="#581c87">hesap vereceğini bilen insan; kul hakkına riayet</text>\n  <text x="383" y="225" font-size="10.5" fill="#581c87">eder, toplumda güven, emanet ve adalet yayılır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
